parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Threat triage agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize alert').item.json;
const asset = $json; // fresh asset-inventory read
const rec = out?.recommendation;
const contain = rec === 'isolate_host' || rec === 'block_indicator';
const verdict = out?.verdict;
const score = out?.score;
const isPrivateIp = (v) => /^(10\.|127\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/.test(String(v));
const noop = rec === 'close_benign';

if (out && !(Number.isInteger(score) && score >= 0 && score <= 100)) reasons.push('score ' + score + ' is not an integer from 0 to 100');
if (rec === 'escalate_to_human') reasons.push('agent asks for a person');

// The target must exist, now, in the inventory.
if (!asset?.asset_id) reasons.push('asset ' + (out?.target_asset_id ?? req.asset_id) + ' not found in the asset inventory');
else if (out?.target_asset_id && asset.asset_id !== out.target_asset_id) reasons.push('inventory returned ' + asset.asset_id + ', not the proposed target ' + out.target_asset_id);
if (asset?.status && asset.status !== 'active') reasons.push('asset ' + asset.asset_id + ' is ' + asset.status + ' in the inventory');

// Safety-critical OT: a person decides, with no automated containment.
const safetyClass = (cfg.no_containment_classes ?? []).includes(asset?.asset_class);
if (asset?.safety_critical === true || safetyClass || out?.safety_critical_involved) {
  reasons.push('SAFETY: ' + (asset?.asset_id ?? req.asset_id) + ' is ' + (safetyClass ? 'a ' + asset.asset_class : 'flagged safety-critical') + '. A person decides containment; nothing automated');
}

// Verdict and recommendation must agree.
if ((verdict === 'benign' || verdict === 'false_positive') && contain) reasons.push('containment proposed on a ' + verdict + ' verdict');
if (noop && !(verdict === 'benign' || verdict === 'false_positive')) reasons.push('closure proposed on a ' + verdict + ' verdict');
if (noop && !String(out?.closing_notes ?? '').trim()) reasons.push('closure without closing notes');
if (contain && Number.isInteger(score) && score < cfg.min_score_for_containment) reasons.push('containment proposed at score ' + score + ', below the floor of ' + cfg.min_score_for_containment);

if (rec === 'isolate_host') {
  if ((asset?.domain ?? req.domain) === 'ot' && !cfg.isolate_ot_hosts) reasons.push('host isolation on an OT asset is turned off in Config');
}
if (rec === 'block_indicator') {
  const ind = out?.indicator;
  if (!ind?.value) reasons.push('block proposed without an indicator');
  else {
    if (!req.indicators.some((i) => i.value === ind.value)) reasons.push('indicator ' + ind.value + ' is not in the alert');
    if (ind.type === 'ip' && isPrivateIp(ind.value)) reasons.push('indicator ' + ind.value + ' is a private or local address');
    if ((cfg.protected_indicators ?? []).includes(ind.value)) reasons.push('indicator ' + ind.value + ' is on the protected list');
  }
  if (!(cfg.allowed_enforcement_points ?? []).includes(out?.enforcement_point)) reasons.push('enforcement point ' + out?.enforcement_point + ' is not allowed');
}

const action = {
  type: rec,
  alert_id: req.alert_id,
  asset_id: asset?.asset_id ?? out?.target_asset_id ?? req.asset_id,
  hostname: asset?.hostname ?? req.hostname,
  indicator: rec === 'block_indicator' ? out?.indicator ?? null : null,
  enforcement_point: rec === 'block_indicator' ? out?.enforcement_point ?? null : rec === 'isolate_host' ? 'edr' : null,
  score: score ?? null,
  verdict: verdict ?? null,
};
const summary = 'Alert ' + req.alert_id + ' (' + req.domain.toUpperCase() + ', ' + req.rule_name + ') on ' + action.asset_id + ' ' + action.hostname + '.\n'
  + 'Verdict *' + verdict + '*, score ' + score + '.\n'
  + 'Proposed: *' + rec + '*'
  + (rec === 'block_indicator' ? ' ' + action.indicator?.type + ' ' + action.indicator?.value + ' at ' + action.enforcement_point : '')
  + (rec === 'isolate_host' ? ' via EDR' : '') + '.\n' + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const sameTarget = planned.type === 'isolate_host'
  ? $json.asset_id === planned.asset_id
  : $json.indicator?.value === planned.indicator?.value && $json.enforcement_point === planned.enforcement_point;
const ok = $json.status === 'executed' && $json.type === planned.type && sameTarget;
const detail = 'SOAR shows ' + $json.type + ' ' + $json.status + ' on ' + ($json.asset_id ?? $json.indicator?.value) + ', expected ' + planned.type + ' executed on ' + (planned.type === 'isolate_host' ? planned.asset_id : planned.indicator?.value);
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize alert').item.json;
let agent = null;
let guard = null;
try { agent = $('Threat triage agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "security operations",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Alert ' + intake.alert_id + ' · ' + intake.domain.toUpperCase() + ' · ' + intake.asset_id + ' · ' + (agent?.output?.verdict ?? 'not triaged') + ' · score ' + (agent?.output?.score ?? 'n/a') + ' · proposed ' + (agent?.output?.recommendation ?? 'none'),
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

parameters.jsCode:
const intake = $('Normalize alert').item.json;
let agent = null;
let guard = null;
let approval = null;
try { agent = $('Threat triage agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = $('Record approval').item.json; } catch (e) {}

return {
  json: {
    business_key: intake.business_key,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
